from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient

app = FastAPI()


@app.middleware("http")
async def require_key(request: Request, call_next):
    if request.url.path != "/public" and request.headers.get("x-api-key") != "secret":
        return JSONResponse({"detail": "Нужен ключ"}, status_code=401)
    return await call_next(request)


@app.get("/public")
def public():
    return {"open": True}


@app.get("/private")
def private():
    return {"open": False}


client = TestClient(app)
print(client.get("/public").status_code)
print(client.get("/private").status_code)
print(client.get("/private", headers={"X-API-Key": "secret"}).json())
